function buildAlbumView(albums, options = {}) {
  if (!Array.isArray(albums)) throw new TypeError('albums must be an array');
  if (!options || typeof options !== 'object' || Array.isArray(options) ||
      Object.getPrototypeOf(options) !== Object.prototype) {
    throw new TypeError('options must be a plain object');
  }

  const optionKeys = Reflect.ownKeys(options);
  if (optionKeys.some(key => key !== 'query' && key !== 'limit')) {
    throw new TypeError('unknown option');
  }

  const query = options.query === undefined ? '' : options.query;
  if (typeof query !== 'string') throw new TypeError('query must be a string');

  const limit = options.limit === undefined ? albums.length : options.limit;
  if (typeof limit !== 'number' || !Number.isFinite(limit)) {
    throw new TypeError('limit must be a finite number');
  }
  if (!Number.isSafeInteger(limit) || limit < 0) {
    throw new RangeError('invalid limit');
  }

  const ids = new Set();
  const expected = ['id', 'title', 'artist', 'cover'];
  const normalized = albums.map(album => {
    if (!album || typeof album !== 'object' || Array.isArray(album) ||
        Object.getPrototypeOf(album) !== Object.prototype) {
      throw new TypeError('album must be a plain object');
    }
    const keys = Reflect.ownKeys(album);
    if (keys.length !== expected.length ||
        expected.some(key => !Object.prototype.hasOwnProperty.call(album, key))) {
      throw new TypeError('invalid album fields');
    }
    for (const key of expected) {
      if (typeof album[key] !== 'string' || album[key].length === 0) {
        throw new TypeError(key + ' must be non-empty');
      }
    }
    if (ids.has(album.id)) throw new RangeError('duplicate id');
    ids.add(album.id);
    return {
      id: album.id,
      title: album.title,
      artist: album.artist,
      cover: album.cover
    };
  });

  const needle = query.toLocaleLowerCase();
  const matches = normalized.filter(album =>
    album.title.includes(needle) || album.artist.includes(needle)
  );
  const cards = matches.slice(0, limit).map(album => Object.freeze({
    id: album.id,
    heading: album.title,
    subtitle: album.artist,
    image: album.cover
  }));

  return Object.freeze({
    total: matches.length,
    cards: Object.freeze(cards)
  });
}

module.exports = { buildAlbumView };

