'use strict';
const assert = require('node:assert');
const { buildAlbumView } = require('./solution');

assert.deepStrictEqual(Object.keys(require('./solution')), ['buildAlbumView']);

const albums = [
  { id: '1', title: 'Blue Sky', artist: 'Alpha', cover: '/1.jpg' },
  { id: '2', title: 'Night', artist: 'The BLUE Band', cover: '/2.jpg' },
  { id: '3', title: 'Green', artist: 'Gamma', cover: '/3.jpg' }
];
const original = JSON.parse(JSON.stringify(albums));
const view = buildAlbumView(albums, { query: 'bLuE', limit: 1 });
assert.deepStrictEqual(view, {
  total: 2,
  cards: [{ id: '1', heading: 'Blue Sky', subtitle: 'Alpha', image: '/1.jpg' }]
});
assert.ok(Object.isFrozen(view));
assert.ok(Object.isFrozen(view.cards));
assert.ok(Object.isFrozen(view.cards[0]));
assert.deepStrictEqual(albums, original);

albums[0].title = 'Changed';
assert.strictEqual(view.cards[0].heading, 'Blue Sky');
assert.throws(() => { view.cards[0].heading = 'x'; }, TypeError);
assert.throws(() => view.cards.push({}), TypeError);

const all = buildAlbumView(original);
assert.strictEqual(all.total, 3);
assert.deepStrictEqual(all.cards.map(card => card.id), ['1', '2', '3']);
assert.deepStrictEqual(buildAlbumView(original, { limit: 0 }), { total: 3, cards: [] });
assert.deepStrictEqual(buildAlbumView([], { query: 'x' }), { total: 0, cards: [] });
assert.notStrictEqual(buildAlbumView(original).cards[0], buildAlbumView(original).cards[0]);

for (const bad of [null, {}, 'albums']) assert.throws(() => buildAlbumView(bad), TypeError);
assert.throws(() => buildAlbumView([{ id: '1', title: 'T', artist: 'A', cover: 'C' }, { id: '1', title: 'U', artist: 'B', cover: 'D' }]), RangeError);
assert.throws(() => buildAlbumView([{ id: '', title: 'T', artist: 'A', cover: 'C' }]), TypeError);
assert.throws(() => buildAlbumView([{ id: '1', title: 'T', artist: 'A', cover: 'C', extra: 1 }]), TypeError);
assert.throws(() => buildAlbumView([Object.assign(Object.create({ inherited: true }), { id: '1', title: 'T', artist: 'A', cover: 'C' })]), TypeError);

for (const options of [null, [], { query: 1 }, { limit: '1' }, { extra: 1 }, Object.assign(Object.create({ inherited: true }), { query: '' })]) {
  assert.throws(() => buildAlbumView(original, options), TypeError);
}
for (const limit of [-1, 1.5, Number.MAX_SAFE_INTEGER + 1]) {
  assert.throws(() => buildAlbumView(original, { limit }), RangeError);
}

